const D = { wear: .5, scale: 1, energy: .6, density: .5, hue: 96, speed: 1, x: .5, y: .40, alpha: 1, style: 'jaspe', act: 'dolly', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255,(g+m)*255,(l+m)*255]; };
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style, act=P.act;
const wr=cl(P.wear,0,1.4), sc=cl(P.scale,.4,2.4), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4), en=cl(P.energy,0,1);
const H=md(P.hue,360), T=K.t*spd;
const TD=K.t*(.45+.55*Math.min(spd,3));

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;

// ---- seeded wrapping fBm field (once per seed) ----
const NZ=160;
if(S.nzK!==P.seed || !S.nz){ S.nzK=P.seed; const F=new Float32Array(NZ*NZ); let amp=1, tot=0;
  for(let o=0;o<4;o++){ const per=4<<o, cell=NZ/per;
    const lv=new Float32Array(per*per);
    for(let k=0;k<per*per;k++) lv[k]=fr(o*977.3+k*1.317+3.7);
    for(let j=0;j<NZ;j++){ const gy=j/cell, jy=Math.floor(gy), fy=gy-jy, vv=fy*fy*(3-2*fy);
      const j0=(jy%per)*per, j1=((jy+1)%per)*per;
      for(let i=0;i<NZ;i++){ const gx=i/cell, ix=Math.floor(gx), fx=gx-ix, uu=fx*fx*(3-2*fx);
        const i0=ix%per, i1=(ix+1)%per;
        const a=lv[j0+i0], b=lv[j0+i1], c=lv[j1+i0], d=lv[j1+i1];
        F[j*NZ+i]+=amp*(a+(b-a)*uu+(c-a)*vv+(a-b-c+d)*uu*vv); } }
    tot+=amp; amp*=0.52; }
  for(let k=0;k<NZ*NZ;k++) F[k]=F[k]/tot;
  S.nz=F; }
const NF=S.nz, CEL=NZ/4;
const nzAt=(x,y)=>{ x*=CEL; y*=CEL;
  let xi=Math.floor(x), yi=Math.floor(y); const fx=x-xi, fy=y-yi;
  xi=md(xi,NZ); yi=md(yi,NZ); const x1=(xi+1)%NZ, y1=(yi+1)%NZ, r0=yi*NZ, r1=y1*NZ;
  const a=NF[r0+xi], b=NF[r0+x1], c=NF[r1+xi], d=NF[r1+x1];
  return a+(b-a)*fx+(c-a)*fy+(a-b-c+d)*fx*fy; };

const BW=Math.max(360,Math.min(720,Math.round(W/2.4))), BH=cl(Math.round(BW*Hh/Math.max(1,W)),60,720);
if(!S.g || S.gk!==BW+'x'+BH){ if(S.g&&S.g.remove)S.g.remove();
  S.g=createGraphics(BW,BH); S.gk=BW+'x'+BH; }
const G=S.g;

// ---- dramaturgy ----
const sec=((K.section|0)%8+8)%8;
let dolly, buffK, scuffF;
if(act==='buff'){ dolly=.25; buffK=2.4; scuffF=.7; }
else if(act==='scuff'){ dolly=.7; buffK=.7; scuffF=.5+1.9*(.5+.5*Math.sin(sec*.85+T*.019)); }
else { dolly=1; buffK=1; scuffF=1; }

// ---- the camera dollies down the corridor and the strip lights walk the wax. Both
// monotonic: neither can re-phase away over an 8s window.
const scroll=.26*TD*dolly;
const lAz=cl(P.x,0,1)*TAU + .0165*TD*buffK + .22*Math.sin(TD*.047*buffK) + .11*Math.sin(TD*.105*buffK+1.4);
// overhead fluorescent tubes — a waxed floor smears each one into a long soft column
const NLM=3;
const lampX=[], lampA=[];
for(let k=0;k<NLM;k++){
  lampX.push((fr(k*5.7+400)-.5)*2.0 + .30*Math.sin(lAz*(.7+.2*k)+k*2.3));
  lampA.push(.5+.5*fr(k*5.7+401));
}

// ---- style ----
let LINO, JASP, BACKING, SEAM, LAMP, wmap=0, vct=0;
if(sty==='vct'){ LINO=hsb2rgb(H+8,7,66); JASP=hsb2rgb(H+2,16,44); BACKING=hsb2rgb(H-70,26,40); SEAM=hsb2rgb(H+6,10,42); LAMP=[248,252,255]; vct=1; }
else if(sty==='worn'){ LINO=hsb2rgb(H-4,22,40); JASP=hsb2rgb(H+6,30,26); BACKING=hsb2rgb(H-72,34,44); SEAM=hsb2rgb(H,26,20); LAMP=[250,250,244]; }
else if(sty==='oxblood'){ LINO=hsb2rgb(H-88,44,28); JASP=hsb2rgb(H-80,52,16); BACKING=hsb2rgb(H-70,30,42); SEAM=hsb2rgb(H-88,48,12); LAMP=[255,240,220]; }
else if(sty==='wearmap'){ LINO=hsb2rgb(H+150,40,10); JASP=hsb2rgb(H+120,30,26); BACKING=hsb2rgb(H-40,80,92); SEAM=hsb2rgb(H+150,20,6); LAMP=[200,240,255]; wmap=1; }
else { LINO=hsb2rgb(H,26,50); JASP=hsb2rgb(H+10,34,32); BACKING=hsb2rgb(H-74,32,44); SEAM=hsb2rgb(H+4,28,26); LAMP=[250,252,246]; }

// ---- the plane ----
const hz=cl(P.y,.20,.74)*Hh, gH=Math.max(24,Hh-hz);
const vpx=cl(P.x,.05,.95)*W;
const jasF=(3.2+dens*4.0)/Math.max(.35,sc);
const tileW=.40*sc;
const glow=(.35+.95*en)*(.55+.7*K.intensity)+S.tre*.3*en;

G.loadPixels();
const px=G.pixels;
for(let j=0;j<BH;j++){
  const sy=(j/BH)*Hh;
  const o0=j*BW*4;
  if(sy<=hz+.5){ for(let i=0;i<BW;i++) px[o0+i*4+3]=0; continue; }
  const t=cl((sy-hz)/gH,0.0001,1);
  const persp=1/(t*t*1.55+.105);
  const lodMix=cl(1.25/(1+persp*.42),0,1);     // the pattern loses its grain as it recedes
  const rowW=(W*.5)/(persp*.30+.30);
  const wz=persp*.90+scroll;
  const fade=cl(1-Math.pow(1-t,2.4)*1.05,0,1);
  for(let i=0;i<BW;i++){
    const sx=(i/BW)*W;
    const wx=((sx-vpx)/Math.max(1e-4,rowW))*2.6/sc;
    const o=o0+i*4;
    // jaspe: lino is marbled by dragging two colours of mix together, so the streaks
    // run long in one direction and stay tight across it — never an isotropic blob
    const q=(nzAt(wx*.55+3.1, wz*.55+8.8)-.5)*1.1;
    const j1=nzAt(wx*jasF*.30+q*1.3+11.1, wz*jasF*.055+q*.5+3.3);
    const j2=nzAt(wx*jasF*.83-q*.9-5.5, wz*jasF*.152+q*.8+8.8);
    const j3=nzAt(wx*jasF*1.97+q*.6+2.7, wz*jasF*.361-q*.4+19.4);
    let jasp=cl((j1*.50+j2*.42+j3*.38-.55)*3.2,0,1);
    jasp=.5+(jasp-.5)*lodMix*(1-cl(wr*.30,0,.5));
    let R,Gc,B;
    R=LINO[0]+(JASP[0]-LINO[0])*jasp; Gc=LINO[1]+(JASP[1]-LINO[1])*jasp; B=LINO[2]+(JASP[2]-LINO[2])*jasp;
    // VCT: chips of filler pressed into 12-inch tiles, with a hard grid between them
    if(vct){
      const spk=cl((nzAt(wx*jasF*3.1+31.1, wz*jasF*3.1+17.7)-.50)*4.0,0,1)*lodMix;
      R=R+(JASP[0]-R)*spk*.85; Gc=Gc+(JASP[1]-Gc)*spk*.85; B=B+(JASP[2]-B)*spk*.85;
    }
    // the welded seams between sheets — or the tile grid on VCT
    const tu=wx/(vct?tileW:tileW*3.1), tv=wz/(vct?tileW:tileW*3.1);
    const ju=Math.abs(tu-Math.round(tu)), jv=Math.abs(tv-Math.round(tv));
    const seam=cl(1-(vct?Math.min(ju,jv):jv)/(.016+.010*dens),0,1)*lodMix;
    R=R+(SEAM[0]-R)*seam*.8; Gc=Gc+(SEAM[1]-Gc)*seam*.8; B=B+(SEAM[2]-B)*seam*.8;
    // traffic: a path is walked down the middle. The wax goes first, then the wear layer,
    // and finally the jute backing comes through.
    const wn=nzAt(wx*.5+41.1, wz*.22+3.3);
    const lane=Math.exp(-Math.pow(wx/(.85*sc),2))*(.45+.55*wn);
    const path=wr*(.34+.80*lane);                 // wear reaches the whole floor, worst in the lane
    const through=cl((path-.62)*2.4,0,1)*scuffF;
    R=R+(BACKING[0]-R)*through*.8; Gc=Gc+(BACKING[1]-Gc)*through*.8; B=B+(BACKING[2]-B)*through*.8;
    // heel marks: black arcs scuffed into the wax where people turn
    const hm=cl((nzAt(wx*2.6+7.7, wz*1.1+13.3)-.58)*4.2,0,1)*cl(path*1.5,0,1)*scuffF*.8;
    R*=(1-hm*.55); Gc*=(1-hm*.55); B*=(1-hm*.55);
    // the wax: thick and glassy at the edges where the buffer never reaches, gone in the path
    const wax=cl((1-path*.85)*(.35+.65*buffK*.5),0,1);
    let st=0;
    for(let k=0;k<NLM;k++){
      const wid=(.05+.36*(1-t))*sc*(1+(1-wax)*3.4);
      const d=(wx-lampX[k])/wid;
      st+=lampA[k]*Math.exp(-d*d)*(.28+.95*t);
    }
    const rip=1+.28*(nzAt(wx*1.9+7.7, wz*.5+2.2)-.5)*(1-wax*.5);
    const sp=cl(st*Math.pow(wax,.8)*1.35*glow*rip*(.3+.9*fade)*(1-seam*.6),0,3.0)*(wmap?30:70);
    R+=LAMP[0]*sp/255; Gc+=LAMP[1]*sp/255; B+=LAMP[2]*sp/255;
    if(wmap){
      // non-representational: a traffic-density plot — footfall as false-colour contour
      // bands. No lino, no corridor, no light: the wear pattern alone.
      const dv=cl(path*1.15+hm*.4+through*.5,0,1);
      const band=Math.abs(md(dv*7,1)-.5)*2;
      const li=Math.pow(cl(1-band*1.4,0,1),1.4);
      const v=cl(.10+.30*dv+.80*li*fade,0,1.3);
      R=LINO[0]*(1-v*.7)+BACKING[0]*v; Gc=LINO[1]*(1-v*.7)+BACKING[1]*v; B=LINO[2]*(1-v*.7)+BACKING[2]*v;
    }
    // haze the far floor into the horizon so the plane really recedes
    const hf=1-fade;
    R=R*(1-hf*.70)+LINO[0]*hf*.70*.8; Gc=Gc*(1-hf*.70)+LINO[1]*hf*.70*.8; B=B*(1-hf*.70)+LINO[2]*hf*.70*.85;
    px[o]=R<0?0:R>255?255:R; px[o+1]=Gc<0?0:Gc>255?255:Gc; px[o+2]=B<0?0:B>255?255:B; px[o+3]=255;
  }
}
G.updatePixels();

noStroke();
if(al<1){ push(); drawingContext.globalAlpha=al; image(G,0,0,W,Hh); pop(); }
else image(G,0,0,W,Hh);
const dc=drawingContext;
blendMode(BLEND); dc.globalAlpha=1; dc.shadowBlur=0; noStroke(); noTint();
